// Generates static HTML mockups into ../mockups. Run: node build-mockups.mjs
import fs from 'node:fs';
const out = new URL('../mockups/', import.meta.url);
const NAV = [['home','🏠','Hôm nay'],['book','📒','Nhật ký'],['add','+','Thêm'],['chart','📊','Báo cáo'],['user','👤','Hồ sơ']];
const SIDE = [['home','🏠','Hôm nay'],['book','📒','Nhật ký'],['recipe','🍲','Công thức'],['chart','📊','Báo cáo'],['user','👤','Hồ sơ & cài đặt']];
const bottom = a => `<nav class="bottom-nav" aria-label="Điều hướng chính">${NAV.map(([k,i,l])=>k==='add'?`<a class="fab" href="#" aria-label="Thêm món"><b>+</b></a>`:`<a href="#" class="${k===a?'on':''}" ${k===a?'aria-current="page"':''}><span class="ic" aria-hidden="true">${i}</span>${l}</a>`).join('')}</nav>`;
const side = a => `<aside class="sidebar"><div class="logo">🥗 NutriTrack</div>${SIDE.map(([k,i,l])=>`<a href="#" class="${k===a?'on':''}" ${k===a?'aria-current="page"':''}><span aria-hidden="true">${i}</span>${l}</a>`).join('')}<div class="grow"></div><button class="btn" style="margin-top:8px">+ Thêm món</button></aside>`;
const phone = (inner, theme='light', nav='home', extra='') => `<div class="app m" data-theme="${theme}"><div class="statusbar"><span>9:41</span><span>●●● 100%</span></div>${inner}${nav?bottom(nav):''}${extra}</div>`;
const desk = (inner, theme='light', nav='home', extra='') => `<div class="app d" data-theme="${theme}">${side(nav)}<main class="main">${inner}</main>${extra}</div>`;
const deskC = (...a) => desk(...a).replace('class="app d"','class="app d compact"');
const fig = (cap, html) => `<figure><figcaption>${cap}</figcaption>${html}</figure>`;
const page = (title, sub, body) => `<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} — NutriTrack mockup</title><link rel="stylesheet" href="mock.css"></head><body><p><a href="index.html">← Tất cả màn hình</a></p><h1 class="page">${title}</h1><p class="sub">${sub}</p>${body}</body></html>`;
const ring = (pct, size, stroke, label, sub, col='var(--kcal)') => { const r=(size-stroke)/2, c=2*Math.PI*r; return `<div class="ring" style="width:${size}px;height:${size}px" role="img" aria-label="${label} ${sub}"><svg width="${size}" height="${size}"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="var(--track)" stroke-width="${stroke}"/><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="${col}" stroke-width="${stroke}" stroke-linecap="round" stroke-dasharray="${c*pct} ${c}"/></svg><div class="center"><div class="big" style="font-size:${size>150?36:28}px">${label}</div><div class="small muted">${sub}</div></div></div>`; };
const macro = (k,name,v,t,u='g') => { const cls={p:'p',c:'c',f:'f'}[k]; return `<div><div class="mlabel"><span><span class="dot ${cls}"></span> ${name}</span><span class="t${cls}">${v}/${t}${u}</span></div><div class="mbar" role="progressbar" aria-valuenow="${v}" aria-valuemax="${t}" aria-label="${name}"><i class="${cls}-fill" style="width:${Math.min(100,v/t*100)}%"></i></div></div>`; };
const food = (e,n,s,k,p='') => `<div class="item"><div class="thumb" aria-hidden="true">${e}</div><div class="grow"><div style="font-weight:600">${n}</div><div class="small muted">${s}</div></div>${p}<div style="text-align:right"><b>${k}</b><div class="xs muted">kcal</div></div></div>`;
const search = ph => `<div class="input" role="search"><span aria-hidden="true">🔍</span><span class="muted">${ph}</span></div>`;

/* ---------- Dashboard ---------- */
const weightCard = hidden => hidden
 ? `<div class="card"><div class="between row"><h3>Cân nặng</h3><button class="btn ghost sm" aria-pressed="true" aria-label="Hiện số cân nặng">👁 Hiện</button></div><div class="between row"><div class="big" style="font-size:32px" aria-label="Số cân nặng đang ẩn">•••• <span class="small muted">kg</span></div></div><p class="small muted" style="margin-top:8px">Số cân nặng đang được ẩn. Bạn vẫn có thể ghi cân nặng; xu hướng không hiển thị trên Dashboard.</p></div>`
 : `<div class="card"><div class="between row"><h3>Cân nặng</h3><button class="btn ghost sm" aria-pressed="false" aria-label="Ẩn số cân nặng">🙈 Ẩn</button></div><div class="between row"><div class="big" style="font-size:32px">68,4 <span class="small muted">kg</span></div><span class="badge ok">↓ 0,6 kg / tuần</span></div><svg class="chart" viewBox="0 0 300 80" role="img" aria-label="Cân nặng giảm từ 70 xuống 68,4 kg"><polyline fill="none" stroke="var(--chart-line)" stroke-width="3" points="0,20 50,28 100,26 150,40 200,44 250,52 300,56"/><circle cx="300" cy="56" r="5" fill="var(--chart-line)"/></svg></div>`;
const dashBody = (big) => `
 <div class="card ${big?'':''}"><div class="row ${big?'':'between'}" style="${big?'gap:32px':''}">${ring(0.62,big?180:150,big?16:14,'760','kcal còn lại')}<div class="grow col" style="gap:8px"><div class="between row"><span class="muted small">Đã ăn</span><b>1.240</b></div><div class="between row"><span class="muted small">Mục tiêu</span><b>2.000</b></div><span class="badge ok" style="align-self:flex-start">Đang đúng kế hoạch</span></div></div></div>
 <div class="card col">${macro('p','Đạm (P)',68,120)}${macro('c','Tinh bột (C)',142,230)}${macro('f','Béo (F)',38,65)}</div>
 <div class="card"><div class="between row"><h3>💧 Nước uống</h3><span class="small muted">1.250 / 2.000 ml</span></div><div class="mbar" style="margin:10px 0 12px"><i style="width:62%;background:var(--water)"></i></div><div class="row"><button class="btn secondary sm">+ 250 ml</button><button class="btn secondary sm">+ 500 ml</button><button class="btn ghost sm">Tuỳ chỉnh</button></div></div>`;
const meals = `<div class="card"><div class="between row"><h3>Bữa hôm nay</h3><a class="small" style="color:var(--link);font-weight:600" href="#">Xem nhật ký</a></div>
 ${['🌅 Sáng|420|2 món','🍚 Trưa|620|3 món','🥣 Tối|0|Chưa ghi','🍎 Phụ|200|1 món'].map(s=>{const[a,b,c]=s.split('|');return `<div class="item"><div class="grow"><b>${a}</b><div class="small muted">${c}</div></div><b>${b} kcal</b><button class="icon-btn" aria-label="Thêm món vào bữa ${a}">+</button></div>`}).join('')}</div>`;
const dashM = (t,hideW=false) => phone(`<div class="scroll"><div class="between row"><div><div class="small muted">Thứ Tư, 04/11</div><h1>Xin chào, Minh 👋</h1></div><button class="icon-btn" aria-label="Thông báo">🔔</button></div>${dashBody(false)}${meals}${weightCard(hideW)}</div>`, t, 'home');
const dashD = t => desk(`<div class="between row"><div><div class="small muted">Thứ Tư, 04/11/2026</div><h1>Xin chào, Minh 👋</h1></div><div class="row"><button class="icon-btn" aria-label="Ngày trước">‹</button><b>Hôm nay</b><button class="icon-btn" aria-label="Ngày sau">›</button></div></div><div class="grid g12"><div class="col" style="gap:16px">${dashBody(true)}</div><div class="col" style="gap:16px">${meals}${weightCard(false)}</div></div>`, t, 'home');
fs.writeFileSync(new URL('dashboard.html',out), page('Dashboard hôm nay','Vòng kcal còn lại, thanh macro (P/C/F phân biệt bằng màu + hoạ tiết + chữ cái), nước uống, bữa hôm nay. Light + Dark × Mobile + Desktop.',
 `<div class="stage">${fig('Mobile · Light',dashM('light'))}${fig('Mobile · Dark',dashM('dark'))}${fig('Mobile · Đã ẩn cân nặng (Q6)',dashM('light',true))}</div><div class="stage">${fig('Desktop · Light',dashD('light'))}</div><div class="stage">${fig('Desktop · Dark',dashD('dark'))}</div>`));

/* ---------- Onboarding ---------- */
const stepper = n => `<div class="stepper" role="progressbar" aria-valuenow="${n}" aria-valuemax="4" aria-label="Bước ${n}/4">${[1,2,3,4].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div>`;
const onbShell = (n,title,sub,inner,cta) => phone(`<div class="scroll" style="gap:20px"><div class="between row"><button class="icon-btn" aria-label="Quay lại">‹</button><span class="small muted">Bước ${n}/4</span><span style="width:44px"></span></div>${stepper(n)}<div><h1>${title}</h1><p class="muted">${sub}</p></div>${inner}<div class="grow"></div><button class="btn block">${cta}</button></div>`, 'light', null);
const ob1 = onbShell(1,'Mục tiêu của bạn là gì?','Chúng tôi dùng điều này để tính lượng calo phù hợp.',['🔻|Giảm cân|Thâm hụt ~500 kcal/ngày','⚖️|Giữ cân|Ăn đúng nhu cầu','💪|Tăng cân / tăng cơ|Dư ~300 kcal/ngày'].map((s,i)=>{const[e,a,b]=s.split('|');return `<div class="opt ${i===0?'on':''}" role="radio" aria-checked="${i===0}"><span style="font-size:28px">${e}</span><div><b>${a}</b><div class="small muted">${b}</div></div></div>`}).join(''),'Tiếp tục');
const ob2 = onbShell(2,'Thông tin cơ thể','Dùng để tính BMR & TDEE. Dữ liệu chỉ lưu cho bạn.',`<div class="seg" role="radiogroup" aria-label="Giới tính"><span class="on">Nam</span><span>Nữ</span></div><div class="grid g2"><div class="field"><label for="a">Tuổi</label><div class="input" id="a">28</div></div><div class="field"><label>Chiều cao (cm)</label><div class="input">172</div></div></div><div class="field"><label>Cân nặng hiện tại (kg)</label><div class="input">70</div></div><div class="field"><label>Cân nặng mục tiêu (kg)</label><div class="input error">75 → <span class="muted"> khác hướng với mục tiêu giảm cân</span></div><div class="err">⚠ Cân nặng mục tiêu phải nhỏ hơn 70 kg khi giảm cân.</div></div><div class="field"><label>Mức vận động</label><div class="input">Vận động nhẹ (1–3 buổi/tuần) ▾</div></div>`,'Tiếp tục');
const ob3 = onbShell(3,'Kế hoạch dinh dưỡng của bạn','Ước tính theo công thức Mifflin-St Jeor. Bạn có thể chỉnh sau.',`<div class="card row" style="gap:16px">${ring(1,120,12,'1.900','kcal / ngày')}<div class="grow col" style="gap:6px"><div class="between row small"><span class="muted">BMR</span><b>1.620</b></div><div class="between row small"><span class="muted">TDEE</span><b>2.230</b></div><div class="between row small"><span class="muted">Giảm cân</span><b>−330</b></div></div></div><div class="card col">${macro('p','Đạm (P)',120,120)}${macro('c','Tinh bột (C)',215,215)}${macro('f','Béo (F)',58,58)}</div><div class="small muted">Dự kiến đạt 65 kg sau ~10 tuần (0,5 kg/tuần). Đây không phải tư vấn y tế.</div>`,'Tiếp tục');
const ob4 = onbShell(4,'Bật nhắc nhở?','Giúp bạn ghi bữa ăn và uống nước đều đặn. Có thể tắt bất cứ lúc nào.',`<div class="card col"><div class="between row"><div><b>Nhắc ghi bữa ăn</b><div class="small muted">07:30 · 12:00 · 19:00</div></div><div class="switch" role="switch" aria-checked="true" aria-label="Nhắc ghi bữa ăn"></div></div><div class="between row"><div><b>Nhắc uống nước</b><div class="small muted">Mỗi 2 giờ, 8:00–20:00</div></div><div class="switch" role="switch" aria-checked="true" aria-label="Nhắc uống nước"></div></div></div>`,'Bắt đầu theo dõi 🎉');
const obD = desk(`<div style="max-width:720px;margin:0 auto;width:100%;display:flex;flex-direction:column;gap:24px"><div class="between row"><button class="btn ghost">‹ Quay lại</button><span class="small muted">Bước 3/4</span></div>${stepper(3)}<div><h1>Kế hoạch dinh dưỡng của bạn</h1><p class="muted">Ước tính theo Mifflin-St Jeor. Bạn có thể chỉnh sau trong Hồ sơ.</p></div><div class="grid g2"><div class="card row" style="gap:20px">${ring(1,150,14,'1.900','kcal / ngày')}<div class="grow col" style="gap:6px"><div class="between row small"><span class="muted">BMR</span><b>1.620</b></div><div class="between row small"><span class="muted">TDEE</span><b>2.230</b></div><div class="between row small"><span class="muted">Giảm cân</span><b>−330</b></div></div></div><div class="card col">${macro('p','Đạm (P)',120,120)}${macro('c','Tinh bột (C)',215,215)}${macro('f','Béo (F)',58,58)}</div></div><div class="row" style="justify-content:flex-end"><button class="btn secondary">Chỉnh macro</button><button class="btn">Tiếp tục</button></div></div>`,'light',null).replace(/<aside.*?<\/aside>/s,'');
fs.writeFileSync(new URL('onboarding.html',out), page('Onboarding (4 bước)','Mục tiêu → thông tin cơ thể (có trạng thái lỗi validate) → kết quả BMR/TDEE/macro → nhắc nhở. Desktop: form căn giữa, không sidebar.',
 `<div class="stage">${fig('Bước 1 · Mobile',ob1)}${fig('Bước 2 · Mobile (lỗi validate)',ob2)}${fig('Bước 3 · Mobile',ob3)}${fig('Bước 4 · Mobile',ob4)}</div><div class="stage">${fig('Bước 3 · Desktop',obD)}</div>`));

/* ---------- Add food ---------- */
const results = [['🍜','Phở bò tái','1 tô · 450 g','430'],['🍚','Cơm tấm sườn','1 đĩa · 380 g','740'],['🥖','Bánh mì thịt','1 ổ · 180 g','410'],['🥗','Gỏi cuốn tôm thịt','2 cuốn · 120 g','170']];
const afM = phone(`<div class="scroll"><div class="row"><button class="icon-btn" aria-label="Đóng">✕</button><h2 class="grow">Thêm vào bữa Trưa</h2></div>${search('Tìm món: phở, cơm tấm, bún chả…')}<div class="row" style="overflow:hidden"><span class="chip on">Gần đây</span><span class="chip">Yêu thích</span><span class="chip">Công thức của tôi</span><span class="chip">Tự thêm</span></div><div><h3 class="small muted" style="margin-bottom:4px">GẦN ĐÂY</h3><div class="card" style="padding:4px 16px">${results.map(r=>food(...r,'')).join('')}</div></div><button class="btn secondary block">📷 Quét mã vạch · ✍️ Thêm món mới</button></div>`, 'light', null,
 `<div class="scrim"><div class="sheet" role="dialog" aria-modal="true" aria-label="Chọn khẩu phần"><div class="grab"></div><div class="between row"><h2>Phở bò tái</h2><button class="icon-btn" aria-label="Đóng">✕</button></div><div class="field"><label>Khẩu phần</label><div class="row"><div class="input grow">1 tô (450 g) ▾</div><div class="row"><button class="icon-btn" aria-label="Giảm">−</button><b style="min-width:28px;text-align:center">1</b><button class="icon-btn" aria-label="Tăng">+</button></div></div></div><div class="card" style="box-shadow:none;background:var(--surface-2)"><div class="between row"><b class="big" style="font-size:28px">430 <span class="small muted">kcal</span></b><span class="small"><span class="tp">P 28g</span> · <span class="tc">C 52g</span> · <span class="tf">F 11g</span></span></div></div><div class="field"><label>Bữa</label><div class="seg"><span>Sáng</span><span class="on">Trưa</span><span>Tối</span><span>Phụ</span></div></div><button class="btn block">Thêm vào nhật ký</button></div></div><div class="toast" role="status" style="display:none"></div>`);
const afM2 = phone(`<div class="scroll"><div class="row"><button class="icon-btn" aria-label="Quay lại">‹</button>${search('phở')}</div><div class="small muted">4 kết quả cho “phở”</div><div class="card" style="padding:4px 16px">${[['🍜','Phở bò tái','1 tô · 450 g','430'],['🍜','Phở gà','1 tô · 450 g','380'],['🍜','Phở cuốn','4 cuốn · 160 g','280'],['🥢','Phở xào bò','1 đĩa · 300 g','520']].map(r=>food(...r)).join('')}</div></div><div class="toast" role="status"><span>Đã thêm Phở bò tái vào bữa Trưa</span><b>Hoàn tác</b></div>`,'light',null);
const afM3 = phone(`<div class="scroll"><div class="row"><button class="icon-btn" aria-label="Quay lại">‹</button>${search('canh bí đao xyz')}</div><div class="empty"><div class="art" aria-hidden="true">🔎</div><h3>Không tìm thấy “canh bí đao xyz”</h3><p class="muted small">Thử từ khoá ngắn hơn hoặc tự thêm món này để dùng lại lần sau.</p><button class="btn">+ Tạo món mới</button></div></div>`,'light',null);
const afD = desk(`<div class="between row"><h1>Thêm món vào bữa Trưa</h1><button class="btn ghost">Đóng ✕</button></div><div class="grid" style="grid-template-columns:1.2fr 1fr"><div class="col">${search('Tìm món: phở, cơm tấm, bún chả…')}<div class="row"><span class="chip on">Gần đây</span><span class="chip">Yêu thích</span><span class="chip">Công thức của tôi</span><span class="chip">Tự thêm</span></div><div class="card" style="padding:4px 16px">${results.map((r,i)=>food(...r,'')).join('')}${food('🍲','Bún chả Hà Nội','1 suất · 400 g','620')}</div></div><div class="card col" style="align-self:flex-start"><div class="between row"><h2>Phở bò tái</h2><span class="badge">Đã chọn</span></div><div class="field"><label>Khẩu phần</label><div class="row"><div class="input grow">1 tô (450 g) ▾</div><div class="input" style="width:100px">1</div></div></div><div class="row" style="justify-content:space-around;padding:12px 0">${ring(0.2,96,10,'430','kcal')}<div class="col" style="gap:8px;min-width:160px">${macro('p','Đạm',28,120)}${macro('c','Tinh bột',52,230)}${macro('f','Béo',11,65)}</div></div><div class="field"><label>Bữa</label><div class="seg"><span>Sáng</span><span class="on">Trưa</span><span>Tối</span><span>Phụ</span></div></div><button class="btn block">Thêm vào nhật ký</button></div></div>`,'light','home');
fs.writeFileSync(new URL('add-food.html',out), page('Thêm món','Tìm kiếm + Gần đây + chọn khẩu phần (bottom sheet trên mobile, panel bên phải trên desktop). Kèm trạng thái kết quả, toast hoàn tác, empty.',
 `<div class="stage">${fig('Mobile · Gần đây + chọn khẩu phần (sheet)',afM)}${fig('Mobile · Kết quả tìm kiếm + toast Hoàn tác',afM2)}${fig('Mobile · Empty state',afM3)}</div><div class="stage">${fig('Desktop',afD)}</div>`));

/* ---------- Diary ---------- */
const days = `<div class="row" style="justify-content:space-between" role="tablist" aria-label="Chọn ngày">${['T2 2','T3 3','T4 4','T5 5','T6 6'].map((d,i)=>{const[a,b]=d.split(' ');return `<div role="tab" aria-selected="${i===2}" style="min-width:48px;min-height:56px;border-radius:14px;display:grid;place-items:center;text-align:center;${i===2?'background:var(--primary);color:var(--primary-contrast)':'background:var(--surface);border:1px solid var(--border)'}"><span class="xs">${a}</span><b>${b}</b></div>`}).join('')}</div>`;
const meal = (t,k,items,open=true) => `<div class="card" style="padding:12px 16px"><div class="between row"><h3>${t}</h3><span class="row"><b>${k} kcal</b><button class="icon-btn" aria-label="Thao tác bữa ${t}">⋯</button></span></div>${items?items.map(r=>food(...r)).join(''):`<div class="small muted" style="padding:8px 0">Chưa có món nào.</div>`}<button class="btn ghost sm">+ Thêm món</button></div>`;
const diaryList = `${meal('🌅 Sáng',420,[['🥖','Bánh mì trứng','1 ổ','320'],['☕','Cà phê sữa','1 ly','100']])}${meal('🍚 Trưa',620,[['🍚','Cơm gà xối mỡ','1 đĩa','620']])}${meal('🥣 Tối',0,null)}`;
const diM = phone(`<div class="scroll"><div class="between row"><h1>Nhật ký</h1><button class="icon-btn" aria-label="Chọn ngày trên lịch">📅</button></div>${days}<div class="card row between"><span><b>1.240</b> <span class="muted small">/ 2.000 kcal</span></span><span class="small"><span class="tp">P 68</span> · <span class="tc">C 142</span> · <span class="tf">F 38</span></span></div>${diaryList}</div>`,'light','book',
 `<div class="scrim"><div class="sheet" role="dialog" aria-modal="true" aria-label="Sao chép bữa"><div class="grab"></div><h2>Sao chép bữa Sáng</h2><div class="field"><label>Từ</label><div class="input">Hôm qua · 03/11 (2 món · 410 kcal) ▾</div></div><div class="field"><label>Sang</label><div class="seg"><span>Hôm nay</span><span class="on">Ngày mai</span><span>Chọn ngày</span></div></div><button class="btn block">Sao chép 2 món</button><button class="btn ghost block">Huỷ</button></div></div>`);
const diD = desk(`<div class="between row"><h1>Nhật ký ăn uống</h1><div class="row"><button class="icon-btn" aria-label="Ngày trước">‹</button><b>Thứ Tư, 04/11/2026</b><button class="icon-btn" aria-label="Ngày sau">›</button><button class="btn secondary">📋 Sao chép bữa</button><button class="btn">+ Thêm món</button></div></div><div class="grid g12"><div class="col">${diaryList}</div><div class="col"><div class="card row" style="gap:20px">${ring(0.62,140,13,'760','còn lại')}<div class="grow col" style="gap:10px">${macro('p','Đạm',68,120)}${macro('c','Tinh bột',142,230)}${macro('f','Béo',38,65)}</div></div><div class="card"><h3>Ghi chú</h3><p class="muted small" style="margin-top:6px">Hôm nay ăn nhiều rau hơn. Cần uống thêm nước.</p></div></div></div>`,'light','book');
fs.writeFileSync(new URL('diary.html',out), page('Nhật ký','Xem theo ngày, nhóm theo bữa, tổng kcal/macro, copy bữa từ ngày khác (bottom sheet). Desktop có panel tổng kết bên phải.',
 `<div class="stage">${fig('Mobile · + sheet Sao chép bữa',diM)}</div><div class="stage">${fig('Desktop',diD)}</div>`));

/* ---------- Reports ---------- */
const bars = (n,vals,goal) => { const w=300,h=140; const bw=w/n*0.55; return `<svg class="chart" viewBox="0 0 ${w+40} ${h+24}" role="img" aria-label="Biểu đồ kcal mỗi ngày, mục tiêu ${goal}"><line class="grid" x1="0" x2="${w}" y1="${h*(1-goal/2600)}" y2="${h*(1-goal/2600)}" stroke-dasharray="4 4" stroke="var(--text-faint)"/>${vals.map((v,i)=>{const x=i*(w/n)+(w/n-bw)/2,bh=v/2600*h;return `<rect x="${x}" y="${h-bh}" width="${bw}" height="${bh}" rx="4" fill="${v>goal?'var(--macro-carb)':'var(--kcal)'}"/><text x="${x+bw/2}" y="${h+14}" text-anchor="middle">${n>10&&(i+1)%5?"":i+1}</text>`}).join('')}<text x="${w+2}" y="${h*(1-goal/2600)+4}">${goal}</text></svg>`; };
const wLine = `<svg class="chart" viewBox="0 0 320 130" role="img" aria-label="Cân nặng giảm từ 70 xuống 68,4 kg trong 4 tuần">${[0,1,2,3].map(i=>`<line class="grid" x1="30" x2="320" y1="${10+i*35}" y2="${10+i*35}" stroke-width="1"/>`).join('')}<text x="0" y="14">70</text><text x="0" y="49">69</text><text x="0" y="84">68</text><polyline fill="none" stroke="var(--chart-line)" stroke-width="3" stroke-linejoin="round" points="40,16 110,28 180,34 250,52 310,62"/>${[[40,16],[110,28],[180,34],[250,52],[310,62]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="var(--surface)" stroke="var(--chart-line)" stroke-width="3"/>`).join('')}<text x="40" y="124">T1</text><text x="110" y="124">T2</text><text x="180" y="124">T3</text><text x="250" y="124">T4</text><text x="300" y="124">Nay</text></svg>`;
const stats = `<div class="grid g3"><div class="card"><div class="small muted">TB kcal/ngày</div><div class="big" style="font-size:28px">1.910</div></div><div class="card"><div class="small muted">Ngày đạt mục tiêu</div><div class="big" style="font-size:28px">5/7</div></div><div class="card"><div class="small muted">Nước TB</div><div class="big" style="font-size:28px">1,8 L</div></div></div>`;
const macroAvg = `<div class="card col"><h3>Macro trung bình</h3>${macro('p','Đạm (P)',112,120)}${macro('c','Tinh bột (C)',208,230)}${macro('f','Béo (F)',61,65)}</div>`;
const rpM = phone(`<div class="scroll"><h1>Báo cáo</h1><div class="seg" role="tablist"><span class="on" role="tab" aria-selected="true">Tuần</span><span role="tab">Tháng</span></div><div class="row between"><button class="icon-btn" aria-label="Tuần trước">‹</button><b>27/10 – 02/11</b><button class="icon-btn" aria-label="Tuần sau">›</button></div>${stats.replace('grid g3','grid g3" style="gap:8px')}<div class="card"><h3>Calo mỗi ngày</h3>${bars(7,[1850,2050,1700,1980,2300,1600,1900],2000)}<div class="legend"><span><b style="color:var(--kcal)">■</b> Trong mục tiêu</span><span style="color:var(--macro-carb-text)">■ Vượt mục tiêu</span></div></div>${macroAvg}</div>`,'light','chart');
const rpD = desk(`<div class="between row"><h1>Báo cáo</h1><div class="row"><div class="seg" style="width:220px"><span>Tuần</span><span class="on">Tháng</span></div><button class="icon-btn" aria-label="Tháng trước">‹</button><b>Tháng 10/2026</b><button class="icon-btn" aria-label="Tháng sau">›</button></div></div>${stats}<div class="grid g2"><div class="card"><h3>Calo mỗi ngày</h3>${bars(30,Array.from({length:30},(_,i)=>1600+((i*137)%800)),2000)}</div><div class="card"><div class="between row"><h3>Cân nặng</h3><span class="badge ok">↓ 1,6 kg</span></div>${wLine}<button class="btn secondary sm">+ Ghi cân nặng</button></div></div><div class="grid g2">${macroAvg}<div class="card"><h3>Top món ăn nhiều nhất</h3><table class="t"><tr><th>Món</th><th>Lần</th><th>kcal TB</th></tr><tr><td>Cơm gà xối mỡ</td><td>8</td><td>620</td></tr><tr><td>Phở bò tái</td><td>6</td><td>430</td></tr><tr><td>Bánh mì trứng</td><td>6</td><td>320</td></tr></table></div></div>`,'light','chart');
const rpEmpty = phone(`<div class="scroll"><h1>Báo cáo</h1><div class="empty"><div class="art" aria-hidden="true">📊</div><h3>Chưa đủ dữ liệu</h3><p class="muted small">Ghi ít nhất 3 ngày để xem báo cáo tuần.</p><button class="btn">Ghi bữa đầu tiên</button></div></div>`,'light','chart');
fs.writeFileSync(new URL('reports.html',out), page('Báo cáo tuần/tháng','Tóm tắt, biểu đồ cột kcal (vượt mục tiêu đổi màu + chú giải, không chỉ dựa vào màu), đường cân nặng, macro TB. Chart có aria-label tóm tắt; nên kèm bảng dữ liệu có thể mở.',
 `<div class="stage">${fig('Mobile · Tuần',rpM)}${fig('Mobile · Empty',rpEmpty)}</div><div class="stage">${fig('Desktop · Tháng',rpD)}</div>`));

/* ---------- Profile ---------- */
const sw = (t,s,on=true) => `<div class="between row"><div><b>${t}</b><div class="small muted">${s}</div></div><div class="switch ${on?'':'off'}" role="switch" aria-checked="${on}" aria-label="${t}"></div></div>`;
const profileBody = `<div class="card row" style="gap:16px"><div class="thumb" style="width:56px;height:56px;border-radius:50%;font-size:24px">M</div><div class="grow"><b>Minh Nguyễn</b><div class="small muted">minh@example.com</div></div><button class="btn secondary sm">Sửa</button></div>
<div class="card col"><h3>Mục tiêu dinh dưỡng</h3><div class="between row small"><span class="muted">Mục tiêu</span><b>Giảm cân</b></div><div class="between row small"><span class="muted">Calo / ngày</span><b>1.900 kcal</b></div><div class="between row small"><span class="muted">P / C / F</span><b><span class="tp">120</span> / <span class="tc">215</span> / <span class="tf">58</span> g</b></div><button class="btn secondary sm" style="align-self:flex-start">Tính lại BMR/TDEE</button></div>
<div class="card col"><h3>Nhắc nhở</h3>${sw('Ghi bữa ăn','07:30 · 12:00 · 19:00')}${sw('Uống nước','Mỗi 2 giờ, 8:00–20:00')}${sw('Cân nặng hàng tuần','Chủ nhật 07:00',false)}</div>
<div class="card col"><h3>Giao diện</h3><div class="seg" role="radiogroup" aria-label="Chế độ giao diện"><span>☀️ Sáng</span><span class="on">🌙 Tối</span><span>Theo hệ thống</span></div>${sw('Ẩn số cân nặng','Ẩn trên Dashboard và Báo cáo; vẫn lưu dữ liệu',false)}<div class="between row small"><span>Đơn vị</span><b>kg · cm · ml</b></div></div>
<a class="card between row" href="recipes.html" style="text-decoration:none;color:inherit"><span><b>🍲 Công thức của tôi</b><div class="small muted">3 công thức · tạo, sửa, nhân bản</div></span><span aria-hidden="true">›</span></a>
<button class="btn danger block">Đăng xuất</button>`;
const prM = t => phone(`<div class="scroll"><h1>Hồ sơ</h1>${profileBody}</div>`, t, 'user');
const prD = t => desk(`<h1>Hồ sơ & cài đặt</h1><div class="grid g2"><div class="col">${profileBody.split('<div class="card col"><h3>Nhắc nhở')[0]}</div><div class="col"><div class="card col"><h3>Nhắc nhở</h3>${sw('Ghi bữa ăn','07:30 · 12:00 · 19:00')}${sw('Uống nước','Mỗi 2 giờ, 8:00–20:00')}${sw('Cân nặng hàng tuần','Chủ nhật 07:00',false)}</div><div class="card col"><h3>Giao diện</h3><div class="seg" role="radiogroup" aria-label="Chế độ giao diện"><span>☀️ Sáng</span><span class="${t==='dark'?'on':''}">🌙 Tối</span><span class="${t==='dark'?'':'on'}">Theo hệ thống</span></div>${sw('Ẩn số cân nặng','Ẩn trên Dashboard và Báo cáo; vẫn lưu dữ liệu',false)}</div><a class="card between row" href="recipes.html" style="text-decoration:none;color:inherit"><span><b>🍲 Công thức của tôi</b><div class="small muted">3 công thức</div></span><span aria-hidden="true">›</span></a><div class="card col"><h3>Dữ liệu & tài khoản</h3><button class="btn secondary">Xuất dữ liệu (CSV)</button><button class="btn danger">Xoá tài khoản</button></div></div></div>`, t, 'user');
const modal = phone(`<div class="scroll"></div>`,'light','user',`<div class="scrim c"><div class="modal" style="width:320px" role="alertdialog" aria-modal="true" aria-labelledby="mt"><h2 id="mt">Xoá tài khoản?</h2><p class="muted small">Toàn bộ nhật ký và hồ sơ sẽ bị xoá vĩnh viễn, không thể khôi phục.</p><button class="btn danger">Xoá vĩnh viễn</button><button class="btn secondary">Giữ tài khoản</button></div></div>`);
fs.writeFileSync(new URL('profile.html',out), page('Hồ sơ & cài đặt','Hồ sơ, mục tiêu, nhắc nhở (switch), chế độ sáng/tối/theo hệ thống, xoá tài khoản (modal xác nhận).',
 `<div class="stage">${fig('Mobile · Light',prM('light'))}${fig('Mobile · Dark',prM('dark'))}${fig('Modal xác nhận',modal)}</div><div class="stage">${fig('Desktop · Light',prD('light'))}</div>`));

/* ---------- Components ---------- */
fs.writeFileSync(new URL('components.html',out), page('Component & trạng thái','Button/Input/Select/Tabs/Chip/Badge/Progress/Toast/Empty/Skeleton — mặc định, hover, focus, disabled, error, loading.',
 ['light','dark'].map(t=>`<div class="stage"><div class="app d compact" data-theme="${t}" style="padding:32px;width:1000px;flex-direction:column;gap:24px"><h2>Component · ${t}</h2><div class="row" style="flex-wrap:wrap"><button class="btn">Mặc định</button><button class="btn" style="background:var(--primary-hover)">Hover</button><button class="btn" style="outline:3px solid var(--focus);outline-offset:2px">Focus</button><button class="btn" disabled>Disabled</button><button class="btn">⏳ Đang lưu…</button><button class="btn secondary">Secondary</button><button class="btn ghost">Ghost</button><button class="btn danger">Danger</button></div><div class="grid g3"><div class="field"><label>Mặc định</label><div class="input">Phở bò</div></div><div class="field"><label>Focus</label><div class="input" style="outline:3px solid var(--focus);outline-offset:2px">Phở|</div></div><div class="field"><label>Lỗi</label><div class="input error">-5</div><div class="err">⚠ Giá trị phải lớn hơn 0</div></div></div><div class="tabs"><span class="on">Gần đây</span><span>Yêu thích</span><span>Công thức</span></div><div class="row"><span class="chip on">✓ Đã chọn</span><span class="chip">Chip</span><span class="badge">Mới</span><span class="badge warn">Gần vượt</span><span class="badge err">Vượt</span><span class="badge ok">Đạt</span></div><div class="grid g3"><div class="card col">${macro('p','Đạm',68,120)}${macro('c','Tinh bột',142,230)}${macro('f','Béo',38,65)}</div><div class="card"><div class="col"><div style="height:16px;border-radius:8px;background:var(--surface-2)"></div><div style="height:16px;width:70%;border-radius:8px;background:var(--surface-2)"></div><div class="small muted">Skeleton loading</div></div></div><div class="card empty"><div class="art">🍽️</div><b>Chưa có món nào</b><button class="btn sm">+ Thêm món</button></div></div></div></div>`).join('')));

/* ---------- Recipes (US-22, US-23) ---------- */
const nf = (n,d=0) => n.toLocaleString('vi-VN',{minimumFractionDigits:d,maximumFractionDigits:d});
// per 100 g: kcal, P, C, F, fibre, sugar, sodium(mg)
const ING = [
 {e:'🍗',n:'Ức gà',q:400,u:'g',per:[165,31,0,3.6,0,0,74],f:1},
 {e:'🍚',n:'Gạo tẻ (sống)',q:200,u:'g',per:[350,7.5,77,1,1.3,0.1,5],f:1},
 {e:'🥕',n:'Cà rốt',q:150,u:'g',per:[41,0.9,9.6,0.2,2.8,4.7,69],f:1},
 {e:'🫒',n:'Dầu ăn',q:20,u:'g',per:[884,0,0,100,0,0,0],f:1},
 {e:'🧂',n:'Nước mắm',q:15,u:'ml',per:[35,5,3.6,0,0,3.6,7000],f:1},
];
const tot = list => list.reduce((a,i)=>a.map((v,k)=>v+i.per[k]*i.q/100),[0,0,0,0,0,0,0]);
const NOTE_PORTIONS = 4;
const ingRow = (i,compact) => `<div class="item" style="align-items:center;gap:8px">${compact?'':`<div class="thumb" aria-hidden="true">${i.e}</div>`}<div class="grow"><div style="font-weight:600">${i.n}</div><div class="small muted">${nf(i.per[0]*i.q/100)} kcal</div></div><div class="input" style="width:${compact?60:78}px;min-height:44px;padding:0 8px;justify-content:flex-end" aria-label="Số lượng ${i.n}">${i.q}</div><div class="input" style="width:${compact?52:64}px;min-height:44px;padding:0 6px">${i.u}</div><div hidden></div><button class="icon-btn" aria-label="Xoá nguyên liệu ${i.n}">✕</button></div>`;
const nutri = (list,portions,big) => { const t=tot(list), pp=t.map(v=>v/portions); const cell=(l,v,d=0,u='')=>`<div><div class="xs muted">${l}</div><b>${nf(v,d)}${u}</b></div>`;
 return `<div class="card col" role="region" aria-live="polite" aria-label="Dinh dưỡng công thức, tính lại tự động" style="gap:12px;${big?'':'position:static'}"><div class="between row"><h3>Dinh dưỡng</h3><span class="badge ok">Tính lại tự động</span></div>
 <div class="grid g2" style="gap:12px"><div class="card" style="box-shadow:none;background:var(--surface-2)"><div class="small muted">Cả nồi (${nf(portions,portions%1?1:0)} phần)</div><div class="big" style="font-size:28px">${nf(t[0])} <span class="small muted">kcal</span></div><div class="small" style="margin-top:6px"><span class="tp">P ${nf(t[1])}g</span> · <span class="tc">C ${nf(t[2])}g</span> · <span class="tf">F ${nf(t[3])}g</span></div></div>
 <div class="card" style="box-shadow:none;background:var(--primary-soft);border-color:var(--primary)"><div class="small" style="color:var(--primary-soft-text);font-weight:600">Mỗi phần (1/${nf(portions,portions%1?1:0)})</div><div class="big" style="font-size:28px;color:var(--primary-soft-text)">${nf(pp[0])} <span class="small">kcal</span></div><div class="small" style="margin-top:6px;color:var(--primary-soft-text)"><b>P ${nf(pp[1])}g · C ${nf(pp[2])}g · F ${nf(pp[3])}g</b></div></div></div>
 <div class="grid g3" style="gap:8px">${cell('Chất xơ / phần',pp[4],1,' g')}${cell('Đường / phần',pp[5],1,' g')}${cell('Natri / phần',pp[6],0,' mg')}</div></div>`; };
const recipeCard = (e,n,pt,k,p,c,f,sel) => `<div class="card" ${sel?'style="border:2px solid var(--primary)" aria-current="true"':''}><div class="row"><div class="thumb" aria-hidden="true">${e}</div><div class="grow"><b>${n}</b><div class="small muted">${pt} phần · <b>${k} kcal</b>/phần</div><div class="xs" style="margin-top:2px"><span class="tp">P ${p}g</span> · <span class="tc">C ${c}g</span> · <span class="tf">F ${f}g</span></div></div><button class="icon-btn" aria-label="Thao tác với ${n}" aria-haspopup="menu">⋯</button></div></div>`;
const R1=recipeCard('🍛','Cơm gà rau củ','4',nf(tot(ING)[0]/4),nf(tot(ING)[1]/4),nf(tot(ING)[2]/4),nf(tot(ING)[3]/4),true);
const R2=recipeCard('🍲','Canh rau củ thập cẩm','6','95','4','14','3');
const R3=recipeCard('🥣','Yến mạch sữa chua','1','310','14','46','8');
const menu = `<div role="menu" aria-label="Thao tác công thức" style="position:absolute;right:12px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);box-shadow:var(--shadow-2);padding:4px;min-width:200px;z-index:2"><div role="menuitem" class="item" style="min-height:44px;padding:0 12px">✏️ Sửa</div><div role="menuitem" class="item" style="min-height:44px;padding:0 12px">📄 Nhân bản</div><div role="menuitem" class="item" style="min-height:44px;padding:0 12px;color:var(--danger);font-weight:600">🗑 Xoá công thức…</div></div>`;
const rcListM = phone(`<div class="scroll"><div class="between row"><div class="row"><button class="icon-btn" aria-label="Quay lại">‹</button><h1>Công thức</h1></div><button class="btn sm">+ Tạo</button></div>${search('Tìm công thức của tôi')}<div style="position:relative" class="col">${R1}${R2}${R3}</div><p class="small muted">Công thức xuất hiện trong Thêm món → “Công thức của tôi”, đơn vị “phần”.</p></div>`,'light','user');
const rcMenuM = phone(`<div class="scroll"><div class="between row"><div class="row"><button class="icon-btn" aria-label="Quay lại">‹</button><h1>Công thức</h1></div><button class="btn sm">+ Tạo</button></div>${search('Tìm công thức của tôi')}<div style="position:relative" class="col">${R1}<div style="position:absolute;top:56px;right:0;left:0">${menu.replace('right:12px','right:12px;position:absolute;top:0')}</div>${R2}${R3}</div></div>`,'light','user');
const rcEmptyM = phone(`<div class="scroll"><div class="between row"><h1>Công thức</h1></div><div class="empty"><div class="art" aria-hidden="true">🍲</div><h3>Chưa có công thức nào</h3><p class="muted small">Gộp nhiều nguyên liệu thành một món, chia theo số phần để ghi nhật ký nhanh hơn.</p><button class="btn">+ Tạo công thức đầu tiên</button></div></div>`,'light','user');
const nameField = (v,err) => `<div class="field"><label for="rn">Tên công thức</label><div class="input ${err?'error':''}" id="rn" ${err?'aria-invalid="true" aria-describedby="rn-e"':''}>${v||'<span class="muted">VD: Cơm gà rau củ</span>'}</div>${err?`<div class="err" id="rn-e">⚠ ${err}</div>`:''}</div>`;
const portionField = (v,err) => `<div class="field"><label for="rp">Số khẩu phần (0,5 – 50)</label><div class="row"><button class="icon-btn" aria-label="Giảm 0,5 phần">−</button><div class="input ${err?'error':''}" id="rp" style="width:96px;justify-content:center" ${err?'aria-invalid="true" aria-describedby="rp-e"':''}><b>${v}</b></div><button class="icon-btn" aria-label="Tăng 0,5 phần">+</button><span class="small muted">phần (cho phép 0,5)</span></div>${err?`<div class="err" id="rp-e">⚠ ${err}</div>`:''}</div>`;
const yieldField = `<div class="field"><label for="ry">Khối lượng thành phẩm sau nấu (tuỳ chọn)</label><div class="input" id="ry"><span class="muted">VD 1.200</span><span class="grow"></span>g</div><div class="hint">Nhập để quy đổi sang gam khi ghi nhật ký. Nếu bỏ trống, chỉ dùng đơn vị “phần”.</div></div>`;
